print("""#include "ns3/core-module.h"\n#include "ns3/network-module.h"\n#include "ns3/internet-module.h"\n#include "ns3/wifi-module.h"\n#include "ns3/mobility-module.h"\n#include "ns3/applications-module.h"\n#include "ns3/flow-monitor-module.h"\n\nusing namespace ns3;\n\nNS_LOG_COMPONENT_DEFINE("ns3Agent");\n\nint\nmain(int argc, char *argv[])\n{\n  uint32_t nWifi = 10; // default\n  double simTime = 10.0; // seconds\n  uint16_t echoPort = 9;\n\n  CommandLine cmd(__FILE__);\n  cmd.AddValue("nWifi", "Number of wifi stations", nWifi);\n  cmd.AddValue("simTime", "Simulation time (s)", simTime);\n  cmd.Parse(argc, argv);\n\n  // Create nodes: 1 AP + nWifi STAs\n  NodeContainer wifiStaNodes;\n  NodeContainer wifiApNode;\n  wifiStaNodes.Create(nWifi);\n  wifiApNode.Create(1);\n\n  // Configure channel and phy\n  YansWifiChannelHelper wifiChannel = YansWifiChannelHelper::Default();\n  YansWifiPhyHelper wifiPhy;\n  wifiPhy.SetChannel(wifiChannel.Create());\n  // Optional: set Tx power to a reasonable value\n  wifiPhy.Set("TxPowerStart", DoubleValue(20.0));\n  wifiPhy.Set("TxPowerEnd", DoubleValue(20.0));\n\n  // Wifi helper with 802.11ax\n  WifiHelper wifi;\n  wifi.SetStandard(WIFI_STANDARD_80211ax);\n  wifi.SetRemoteStationManager("ns3::ConstantRateWifiManager",\n                                "DataMode", StringValue("HeMcs0"),\n                                "ControlMode", StringValue("HeMcs0"));\n\n  WifiMacHelper mac;\n  Ssid ssid = Ssid("ns3-80211ax-ssid");\n\n  // STA devices\n  mac.SetType("ns3::StaWifiMac",\n              "Ssid", SsidValue(ssid),\n              "ActiveProbing", BooleanValue(false));\n  NetDeviceContainer staDevices = wifi.Install(wifiPhy, mac, wifiStaNodes);\n\n  // AP device\n  mac.SetType("ns3::ApWifiMac",\n              "Ssid", SsidValue(ssid));\n  NetDeviceContainer apDevice = wifi.Install(wifiPhy, mac, wifiApNode);\n\n  // Mobility: place nodes in a simple layout to avoid overlapping all in one point\n  MobilityHelper mobility;\n  Ptr<ListPositionAllocator> positionAlloc = CreateObject<ListPositionAllocator>();\n  // AP at origin\n  positionAlloc->Add(Vector(0.0, 0.0, 0.0));\n  // STAs in a circle around AP\n  for (uint32_t i = 0; i < nWifi; ++i)\n  {\n    double angle = 2.0 * M_PI * i / nWifi;\n    double radius = 5.0 + (i % 5); // small spread\n    positionAlloc->Add(Vector(radius * std::cos(angle), radius * std::sin(angle), 0.0));\n  }\n  mobility.SetPositionAllocator(positionAlloc);\n  mobility.SetMobilityModel("ns3::ConstantPositionMobilityModel");\n  mobility.Install(wifiApNode);\n  mobility.Install(wifiStaNodes);\n\n  // Internet stack\n  InternetStackHelper stack;\n  stack.Install(wifiApNode);\n  stack.Install(wifiStaNodes);\n\n  // Assign IPs\n  Ipv4AddressHelper address;\n  address.SetBase("192.168.1.0", "255.255.255.0");\n  Ipv4InterfaceContainer apInterface = address.Assign(apDevice);\n  Ipv4InterfaceContainer staInterfaces = address.Assign(staDevices);\n\n  // Install UDP Echo server on AP\n  UdpEchoServerHelper echoServer(echoPort);\n  ApplicationContainer serverApps = echoServer.Install(wifiApNode.Get(0));\n  serverApps.Start(Seconds(0.5));\n  serverApps.Stop(Seconds(simTime + 0.1));\n\n  // Install UDP Echo clients on STAs targeting the AP server\n  for (uint32_t i = 0; i < wifiStaNodes.GetN(); ++i)\n  {\n    UdpEchoClientHelper echoClient(apInterface.GetAddress(0), echoPort);\n    // generate continuous-ish traffic per client\n    echoClient.SetAttribute("MaxPackets", UintegerValue(1000000));\n    echoClient.SetAttribute("Interval", TimeValue(Seconds(0.01)));\n    echoClient.SetAttribute("PacketSize", UintegerValue(1024));\n\n    ApplicationContainer clientApp = echoClient.Install(wifiStaNodes.Get(i));\n    // start after server and association time\n    clientApp.Start(Seconds(1.0 + 0.01 * i));\n    clientApp.Stop(Seconds(simTime + 0.05));\n  }\n\n  // FlowMonitor to collect stats\n  FlowMonitorHelper flowmonHelper;\n  Ptr<FlowMonitor> flowmon = flowmonHelper.InstallAll();\n\n  // Run simulation\n  Simulator::Stop(Seconds(simTime + 0.2));\n  Simulator::Run();\n\n  // Aggregate FlowMonitor statistics\n  flowmon->CheckForLostPackets();\n  Ptr<Ipv4FlowClassifier> classifier = DynamicCast<Ipv4FlowClassifier>(flowmonHelper.GetClassifier());\n  std::map<FlowId, FlowMonitor::FlowStats> stats = flowmon->GetFlowStats();\n\n  uint64_t totalTxPackets = 0;\n  uint64_t totalRxPackets = 0;\n  uint64_t totalLost = 0;\n  double totalDelaySum = 0.0; // seconds\n  uint64_t totalRxBytes = 0;\n\n  for (auto &flow : stats)\n  {\n    FlowId fid = flow.first;\n    const FlowMonitor::FlowStats &fstats = flow.second;\n\n    totalTxPackets += fstats.txPackets;\n    totalRxPackets += fstats.rxPackets;\n    if (fstats.txPackets >= fstats.rxPackets)\n      totalLost += (fstats.txPackets - fstats.rxPackets);\n    else\n      totalLost += 0; // should not happen, but safe\n\n    totalDelaySum += fstats.delaySum.GetSeconds();\n    totalRxBytes += fstats.rxBytes;\n  }\n\n  double avgDelayMs = 0.0;\n  if (totalRxPackets > 0)\n  {\n    avgDelayMs = (totalDelaySum / static_cast<double>(totalRxPackets)) * 1000.0; // ms\n  }\n\n  double throughputMbps = 0.0;\n  if (simTime > 0)\n  {\n    throughputMbps = (static_cast<double>(totalRxBytes) * 8.0) / (simTime * 1e6); // Mbps\n  }\n\n  std::cout << "Total Packet Loss: " << totalLost << " packets" << std::endl;\n  std::cout << "Average Delay (ms): ";\n  if (totalRxPackets > 0)\n    std::cout << avgDelayMs << std::endl;\n  else\n    std::cout << "N/A (no received packets)" << std::endl;\n  std::cout << "Average Throughput (Mbps): " << throughputMbps << std::endl;\n\n  Simulator::Destroy();\n  return 0;""")